NAME = 'CzeCSP: Czech Český studijní překlad'
BOOK = 'I John'

CHAPTERS = {
    1: {
        1: 'Co bylo od počátku, co jsme slyšeli, co jsme na vlastní oči viděli, co jsme spatřili a čeho se naše ruce dotýkaly ohledně Slova života: --',
        2: 'Ten život byl zjeven, viděli jsme a svědčíme a zvěstujeme vám věčný život, který byl u Otce a nám byl zjeven. --',
        3: 'Co jsme viděli a slyšeli, zvěstujeme i vám, abyste také vy měli společenství s námi. Naše společenství je s Otcem a s jeho Synem Ježíšem Kristem.',
        4: 'Toto [vám] píšeme, aby naše radost byla úplná.',
        5: 'A toto je zvěst, kterou jsme od něho slyšeli a vám ji zvěstujeme: Bůh je světlo a není v něm žádná tma.',
        6: 'Řekneme–li, že s ním máme společenství, a přitom chodíme v temnotě, lžeme a nečiníme pravdu.',
        7: 'Jestliže však chodíme v tom světle, jako on je v tom světle, máme společenství mezi sebou a krev Ježíše [Krista], jeho Syna, nás očišťuje od každého hříchu.',
        8: 'Řekneme–li, že žádný hřích nemáme, klameme sami sebe a pravda v nás není.',
        9: 'Jestliže své hříchy vyznáváme, on je věrný a spravedlivý, aby nám hříchy odpustil a očistil nás od každé nepravosti.',
        10: 'Řekneme–li, že jsme nezhřešili, děláme z něj lháře a jeho slovo v nás není.',
    },
    2: {
        1: 'Moje dítky, toto vám píši, abyste nezhřešili; a jestliže by někdo zhřešil, máme u Otce Zastánce, Ježíše Krista, toho spravedlivého.',
        2: 'On je smírčí obětí za naše hříchy, a nejen za naše, ale i za hříchy celého světa.',
        3: 'A podle toho víme, že jsme jej poznali, jestliže zachováváme jeho přikázání.',
        4: 'Kdo říká: Znám ho, a jeho přikázání nezachovává, je lhář a pravda v něm není.',
        5: 'Kdo však zachovává jeho slovo, v tom ⌈se skutečně Boží láska stala dokonalou⌉. Podle toho poznáváme, že jsme v něm.',
        6: 'Kdo říká, že ⌈v něm zůstává⌉, musí sám také žít [tak], jak žil on.',
        7: 'Milovaní, nepíšu vám nové přikázání, ale staré, které jste měli od počátku. To staré přikázání je slovo, které jste [už dávno] slyšeli.',
        8: 'A opět vám píšu přikázání nové, a to je pravdivé v něm i ve vás, že tma pomíjí a to pravé světlo již svítí.',
        9: 'Kdo říká, že je ve světle, a přitom nenávidí svého bratra, je dosud ve tmě.',
        10: 'Kdo svého bratra miluje, zůstává v tom světle a není v něm žádné pohoršení.',
        11: 'Kdo však svého bratra nenávidí, je ve tmě, ve tmě chodí a neví, kam jde; neboť tma oslepila jeho oči.',
        12: 'Píšu vám, dítky, že jsou vám odpuštěny hříchy pro jeho jméno.',
        13: 'Píšu vám, otcové, že jste poznali toho, který je od počátku; píšu vám, mládenci, že jste přemohli toho Zlého.',
        14: 'Napsal jsem vám, dítky, že jste poznali Otce; napsal jsem vám, otcové, že jste poznali toho, který je od počátku; napsal jsem vám, mládenci, že jste silní a slovo Boží ve vás zůstává, a přemohli jste toho Zlého.',
        15: 'Nemilujte svět ani to, co je ve světě. Jestliže někdo miluje svět, není v něm ⌈Otcova láska⌉.',
        16: 'Neboť všechno, co je ve světě -- žádost těla, žádost očí a ⌈prázdná chlouba života⌉ -- není z Otce, ale ze světa.',
        17: 'A svět pomíjí i jeho žádost; kdo však činí vůli Boží, zůstává ⌈na věčnost⌉.',
        18: 'Dítky, je poslední hodina; a jak jste slyšeli, že přichází Antikrist, tak se nyní již objevilo mnoho antikristů; podle toho poznáváme, že je poslední hodina.',
        19: 'Vyšli z nás, ale nebyli z nás. Kdyby byli z nás, zůstali by s námi. Ale to se stalo, aby ⌈vyšlo najevo⌉, že nejsou všichni z nás.',
        20: 'Vy však máte pomazání od toho Svatého a ⌈víte to všichni⌉.',
        21: 'Nenapsal jsem vám proto, že neznáte pravdu, ale proto, že ji znáte a víte, že žádná lež není z pravdy.',
        22: 'Kdo je lhář, ne–li ten, kdo popírá, že Ježíš je Kristus? To je ten antikrist, který popírá Otce i Syna.',
        23: 'Každý, kdo popírá Syna, nemá ani Otce. Kdo vyznává Syna, má i Otce.',
        24: 'Ať ve vás zůstává⌈, co jste slyšeli od počátku. Zůstane–li ve vás to, co jste slyšeli od počátku⌉, zůstanete také vy v Synu a v Otci.',
        25: 'A toto je to zaslíbení, které nám on zaslíbil: věčný život.',
        26: 'Toto jsem vám napsal o těch, kteří vás svádějí.',
        27: 'Ve vás však zůstává pomazání, které jste od něho přijali, a nepotřebujete, aby vás někdo učil; jeho pomazání vás učí všemu a je pravdivé a neklame; jak vás vyučilo, tak zůstávejte v něm.',
        28: 'Nyní tedy, dítky, zůstávejte v něm, abychom nabyli radostné důvěry, až se zjeví, a nebyli jím zahanbeni při jeho příchodu.',
        29: 'Víte–li, že je spravedlivý, vězte, že také každý, kdo činí spravedlnost, je z něho zrozen.',
    },
    3: {
        1: 'Pohleďte, jakou lásku nám Otec dal, abychom byli nazváni Božími dětmi; a také jimi jsme. Proto nás svět nezná, neboť nepoznal jeho.',
        2: 'Milovaní, nyní jsme děti Boží; a ještě se neukázalo, co budeme. Víme však, že až se zjeví, budeme mu podobni, protože ho uvidíme takového, jaký je.',
        3: 'A každý, kdo v něm má tuto naději, očišťuje se, tak jako on je čistý.',
        4: 'Každý, kdo činí hřích, činí také svévoli. Hřích je svévole.',
        5: 'A víte, že on se zjevil, aby odstranil [naše] hříchy, a hříchu v něm není.',
        6: 'Žádný, kdo v něm zůstává, nehřeší. Žádný, kdo hřeší, ho neviděl ani nepoznal.',
        7: 'Dítky, ať vás nikdo nesvádí. Kdo činí spravedlnost, je spravedlivý, tak jako on je spravedlivý.',
        8: 'Kdo činí hřích, je z Ďábla, neboť Ďábel hřeší od počátku. Proto se zjevil Syn Boží, aby zmařil skutky Ďáblovy.',
        9: 'Žádný, kdo je narozen z Boha, nečiní hřích, protože v něm zůstává Boží símě; a nemůže hřešit, protože se narodil z Boha.',
        10: 'Podle toho ⌈se poznají⌉ děti Boží a děti Ďáblovy: žádný, kdo nečiní spravedlnost a kdo nemiluje svého bratra, není z Boha.',
        11: 'Neboť to je ta zvěst, kterou jste slyšeli od počátku: abychom se navzájem milovali.',
        12: 'Ne jako Kain, který byl ze Zlého a zabil svého bratra. A proč ho zabil? Protože jeho vlastní skutky byly zlé, kdežto skutky jeho bratra byly spravedlivé.',
        13: 'Nedivte se, bratři, když vás svět nenávidí.',
        14: 'My víme, že jsme přešli ze smrti do života, neboť milujeme bratry; kdo nemiluje [bratra], zůstává ve smrti.',
        15: 'Každý, kdo nenávidí svého bratra, je vrah; a víte, že žádný vrah nemá věčný život, který by v něm zůstával.',
        16: '⌈Podle toho⌉ jsme poznali lásku, že on za nás položil svou duši. I my jsme povinni položit své duše za bratry.',
        17: 'Má–li však někdo dostatek v tomto světě a vidí, že jeho bratr má nouzi, a zavře před ním své srdce, jak v něm může zůstávat Boží láska?',
        18: 'Dítky, nemilujme slovem ani jazykem, ale v skutku a v pravdě.',
        19: '⌈Podle toho⌉ poznáme, že jsme z pravdy, a tak před ním upokojíme své srdce,',
        20: 'i když by nás naše srdce odsuzovalo; neboť Bůh je větší než naše srdce a zná všechno.',
        21: 'Milovaní, jestliže nás srdce neodsuzuje, máme ⌈radostnou důvěru k Bohu⌉',
        22: 'a oč bychom žádali, dostáváme od něho, protože zachováváme jeho přikázání a činíme to, co se jemu líbí.',
        23: 'A toto je jeho přikázání, abychom uvěřili jménu jeho Syna Ježíše Krista a navzájem se milovali, jak nám přikázal.',
        24: 'Kdo zachovává jeho přikázání, zůstává ⌈v Bohu a Bůh⌉ v něm; že v nás zůstává, poznáváme podle Ducha, kterého nám dal.',
    },
    4: {
        1: 'Milovaní, nevěřte každému duchu, ale zkoumejte duchy, jsou–li z Boha; neboť do světa vyšlo mnoho falešných proroků.',
        2: 'Podle toho poznávejte Ducha Božího: Každý duch, který vyznává Ježíše Krista, jenž přišel v těle, je z Boha.',
        3: 'A žádný duch, který nevyznává Ježíše [Krista, jenž přišel v těle], není z Boha. To je ten duch Antikrista, o němž jste slyšeli, že přichází, a který již nyní je ve světě.',
        4: 'Vy, dítky,jste z Boha a přemohli jste je, neboť ten, který je ve vás, je větší než ten, který je ve světě.',
        5: 'Oni jsou ze světa, proto mluví věci ze světa a svět jim naslouchá.',
        6: 'My jsme z Boha; kdo zná Boha, naslouchá nám, kdo není z Boha, nenaslouchá nám. Podle toho poznáváme Ducha pravdy a ducha bludu.',
        7: 'Milovaní, milujme se navzájem, neboť láska je z Boha, a každý, kdo miluje, se z Boha narodil a Boha zná.',
        8: 'Kdo nemiluje, nepoznal Boha, protože Bůh je láska.',
        9: 'V tom ⌈se ukázala Boží láska k nám⌉, že Bůh na svět poslal svého Syna, toho jediného, abychom skrze něho měli život.',
        10: 'V tom je láska: ne že my jsme si zamilovali Boha, ale že on miloval nás a poslal svého Syna jako oběť smíření za naše hříchy.',
        11: 'Milovaní, jestliže Bůh takto miloval nás, i my se máme navzájem milovat.',
        12: 'Boha nikdo nikdy neviděl. Jestliže se milujeme navzájem, Bůh v nás zůstává a jeho láska v nás ⌈dosáhla svého cíle⌉.',
        13: 'Že zůstáváme v něm a on v nás, poznáváme ⌈podle toho⌉, že nám dal ze svého Ducha.',
        14: 'A my jsme viděli a dosvědčujeme, že Otec poslal Syna, Zachránce světa.',
        15: 'Kdo by vyznal, že Ježíš je Syn Boží, v tom zůstává Bůh a on v Bohu.',
        16: 'A my jsme uvěřili a poznali lásku, kterou Bůh má k nám. Bůh je láska, a kdo zůstává v lásce, zůstává v Bohu a Bůh v něm.',
        17: 'V tom ⌈dosáhla láska při nás cíle⌉, že máme naprostou důvěru pro den soudu, neboť jaký je on, takoví jsme i my v tomto světě.',
        18: 'V lásce není strach, ale dokonalá láska strach zahání; vždyť strach ⌈působí muka⌉, a kdo se bojí, nedošel dokonalosti v lásce.',
        19: 'My milujeme, neboť on první miloval nás.',
        20: 'Řekne–li někdo: Miluji Boha, a přitom nenávidísvého bratra, je lhář. Vždyť kdo nemiluje svého bratra, kterého viděl, nemůže milovat Boha, kterého neviděl.',
        21: 'A toto přikázání máme od něho, aby ten, kdo miluje Boha, miloval také svého bratra.',
    },
    5: {
        1: 'Každý, kdo věří, že Ježíš je Kristus, je zrozen z Boha. A každý, kdo miluje Otce, miluje i ⌈jeho dítě⌉.',
        2: '⌈Podle toho⌉ poznáváme, že milujeme Boží děti, když milujeme Boha a plníme jeho přikázání.',
        3: 'To je totiž láska ⌈ k Bohu⌉, že zachováváme jeho přikázání. A jeho přikázání nejsou těžká,',
        4: 'neboť vše, co se narodilo z Boha, přemáhá svět. A to je to vítězství, které přemohlo svět: naše víra.',
        5: 'Kdo je ten, který přemáhá svět, ne–li ten, kdo věří, že Ježíš je Syn Boží?',
        6: 'To je ten, který přišel skrze vodu a krev: Ježíš Kristus. Ne pouze ve vodě, ale ve vodě a v krvi. A Duch je ten, který to dosvědčuje, neboť Duch je pravda.',
        7: 'Tři jsou, kteří vydávají svědectví [na nebi -- Otec, Slovo a Duch Svatý -- a ti tři jsou jedno].',
        8: '[A jsou tři, kteří vydávají svědectví na zemi] -- Duch, voda a krev --, a ti tři jsou zajedno.',
        9: 'Přijímáme–li svědectví lidí, oč větší je svědectví Boží. Toto je Boží svědectví, protože on sám vydal svědectví o svém Synu.',
        10: 'Kdo věří v Syna Božího, má to svědectví v sobě. Kdo nevěří Bohu, učinil ho lhářem, protože neuvěřil svědectví, které Bůh vydal o svém Synu.',
        11: 'A to je to svědectví: Bůh nám dal věčný život a ten život je v jeho Synu.',
        12: 'Kdo má Syna, má život; kdo nemá Syna Božího, ten život nemá.',
        13: 'Toto jsem napsal vám, kteří věříte ve jméno Syna Božího, abyste věděli, že máte věčný život.',
        14: 'A to je ta naprostá důvěra, kterou máme k němu, že když bychom o něco žádali podle jeho vůle, slyší nás.',
        15: 'A víme–li, že nás slyší, kdykoli o něco žádáme, víme, že máme ⌈to, co⌉ jsme od něho žádali.',
        16: 'Uviděl–li by někdo svého bratra, že hřeší hříchem, který ne ní k smrti, ať za něj poprosí, a Bůh mu dá život; těm, kdo nehřeší k smrti. Je hřích k smrti; u takového neříkám, aby prosil.',
        17: 'Každá nepravost je hřích, ale je i hřích, který ne ní k smrti.',
        18: 'Víme, že kdo je narozen z Boha, nehřeší; ale ten, kdo byl zplozen z Boha, střeží ⌈sebe samého⌉ a ten Zlý se ho nedotýká.',
        19: 'Víme, že jsme z Boha a celý svět leží v tom Zlém.',
        20: 'Víme, že Syn Boží přišel a dal nám schopnost poznávat toho pravého, a jsme v tom pravém, v jeho Synu Ježíši Kristu. On je ten pravý Bůh a věčný život.',
        21: 'Dítky,uchraňte se model! [Amen.]',
    },
}
